pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 fuzzBlockNumber) public {
        // restrict block number so block.number % 15 == 0 can trigger payout
        vm.assume(fuzzBlockNumber % 15 == 0);
        vm.assume(fuzzBlockNumber > 1);
        vm.roll(fuzzBlockNumber);
        address sender = address(0x1);
        vm.deal(sender, 20 ether);
        // first call sets pastBlockTime and possibly triggers transfer (must succeed)
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");
        uint256 balanceBeforeSecond = address(c).balance;
        // second call in same block: reference reverts, mutant allows
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        // assert: if second call succeeds, balance should not increase beyond first call's effect
        // reference always reverts, so ok2 is false; mutant may succeed and increase balance
        assertTrue(!ok2 || address(c).balance == balanceBeforeSecond);
    }
}

