pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 choice, uint256 amount) public {
        // ensure amount is large enough for two 10 ether deposits
        amount = bound(amount, 20 ether, 1000 ether);
        vm.deal(address(this), amount);

        // first call: succeed if block.number % 15 != 0, but we need a successful call to set pastBlockTime
        // We'll make two calls in sequence. For the reference, both can succeed if block conditions permit.
        // For the mutant, the second call always reverts.

        // First call: use block.number such that (block.number % 15) != 0 to avoid transfer, so balance remains
        vm.roll(choice % 15 == 0 ? 1 : choice); // ensure first call doesn't transfer, so balance accumulates
        c.f{value: 10 ether}();

        // Second call: we want a block.number where % 15 == 0 to trigger transfer and thus zero the balance
        // We choose a block number where (block.number-1) % 15 == 0 after rolling
        vm.roll(choice + 15 - ((choice + 1) % 15)); // next multiple of 15
        vm.warp(block.timestamp + 1);
        bool secondOk;
        try c.f{value: 10 ether}() { secondOk = true; } catch { secondOk = false; }

        // The property: if the second call succeeded, the contract's balance must be zero.
        // The reference will succeed and clear the balance; the mutant will revert so balance stays >0.
        assertTrue(!secondOk || address(c).balance == 0);
    }
}

