pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value1, uint256 value2, uint256 blockNumberBase) public {
        // Bound values to admissible domain: exactly 10 ether and blockNumberBase to avoid overflow on block.number checks
        uint256 v1 = bound(value1, 10 ether, 10 ether);
        uint256 v2 = bound(value2, 10 ether, 10 ether);
        // Ensure block.number % 15 calculation doesn't cause issues; bound base to avoid huge block numbers
        uint256 bnum = bound(blockNumberBase, 0, type(uint256).max - 2);

        // We will make two calls at the same block timestamp
        vm.roll(bnum);
        vm.warp(1000);

        // Fund sender
        address sender = address(0x1234);
        vm.deal(sender, 100 ether);

        // First call
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: v1}("");
        assertTrue(ok1); // should succeed

        // Second call at the same timestamp
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: v2}("");

        // The property: the second call must revert because block.timestamp is NOT strictly > pastBlockTime (which was set to current timestamp by first call).
        // The reference contract enforces this, the buggy version does not.
        assertTrue(!ok2);
    }
}

